import { assetPath } from "./asset-path";
import { useEffect, useId, useState, useRef, useMemo, type FormEvent, type ReactNode, type RefObject } from 'react';
import { Pencil1Icon, PlusIcon, Cross1Icon, ChevronDownIcon, ArrowLeftIcon, CheckIcon } from '@radix-ui/react-icons';
import { MobileScroll, KeyboardInput, BottomSheet, useKeyboard, useKeyboardInsets, useScreenPortal } from './mobile';
import '@fontsource/outfit/400.css';
import '@fontsource/outfit/500.css';
import '@fontsource/outfit/600.css';
import '@fontsource/outfit/700.css';
