const feedReadKey='ringstatus-notification-feed-read-v1';
function loadFeedRead(){try{const raw=localStorage.getItem(feedReadKey);if(!raw)return {ids:[] as string[],error:''};const v=JSON.parse(raw);if(v.version!==1||!Array.isArray(v.ids)||!v.ids.every((id:unknown)=>typeof id==='string'))throw Error();return {ids:v.ids as string[],error:''};}catch{return {ids:[] as string[],error:'Saved read state could not be read. Your stored data has not been replaced.'};}}
function NotificationFeed(_props:{active:boolean}){
 const feedId=useId();const [filtersOpen,setFiltersOpen]=useState(false);
 const [initial]=useState(loadFeedRead);const [read,setRead]=useState<string[]>(initial.ids);const [query,setQuery]=useState('');const [kind,setKind]=useState('all');const [ring,setRing]=useState('all');const [rider,setRider]=useState('all');const [unreadOnly,setUnreadOnly]=useState(false);const [,setSelected]=useState<string|null>(null);const [error,setError]=useState(initial.error);const keyboard=useKeyboard();
 const match=(text:string)=>text.toLocaleLowerCase().replace(/[^\p{L}\p{N}]/gu,'');const q=match(query);
 const visible=notificationSamples.filter(r=>(kind==='all'||r.kind===kind)&&(ring==='all'||r.ring===ring)&&(rider==='all'||r.rider===rider)&&(!unreadOnly||!read.includes(r.id))&&(!q||match([r.subject,r.body,r.alert||'',...r.requests].join(' ')).includes(q)));
 function mark(ids:string[]){try{const next=[...new Set([...read,...ids])];localStorage.setItem(feedReadKey,JSON.stringify({version:1,ids:next}));setRead(next);setError('');}catch{setError('Could not save read state. The messages are still available.');}}
 function reset(){keyboard.hide();setQuery('');setKind('all');setRing('all');setRider('all');setUnreadOnly(false);setSelected(null);}
 const filter=(label:string,value:string,onChange:(v:string)=>void,values:string[])=><div className="rings-field"><label htmlFor={`${feedId}-${label}`}>{label}</label><div className="rings-select"><select id={`${feedId}-${label}`} value={value} onFocus={()=>keyboard.hide()} onChange={e=>{keyboard.hide();setSelected(null);onChange(e.target.value);}}><option value="all">All {label.toLowerCase()}s</option>{values.map(v=><option key={v} value={v}>{v}</option>)}</select><ChevronDownIcon aria-hidden="true"/></div></div>;
 return <><MobileScroll className="app-screen rings-screen"><main className="rings-main"><h1>Notifications</h1><p className="rings-help">Your SMS replies and updates, together in one history.</p><div className="rings-scope" role="group" aria-label="Message type">{(['all','reply','update','support'] as const).map(type=><button key={type} className="rings-pill" aria-pressed={kind===type} onClick={()=>{keyboard.hide();setKind(type);setSelected(null);}}>{type==='all'?'All':type==='reply'?'SMS replies':type==='update'?'Updates':'Help'}</button>)}</div><div className="rings-schedule-toolbar"><button className="rings-pill" aria-expanded={filtersOpen} aria-controls={`${feedId}-filters`} onClick={()=>{keyboard.hide();setFiltersOpen(v=>!v);}}>Filters <ChevronDownIcon/></button><label className="rings-rollups-toggle"><input type="checkbox" checked={unreadOnly} onChange={e=>{setUnreadOnly(e.target.checked);setSelected(null);}}/>Unread only</label></div>{filtersOpen?<div className="rings-control-stack" id={`${feedId}-filters`}><TextField label="Search messages" value={query} onChange={v=>{setQuery(v);setSelected(null);}} placeholder="Ring, rider, horse, class or back number"/><div className="rings-filter-grid">{filter('Ring',ring,setRing,[...new Set(notificationSamples.flatMap(r=>r.ring?[r.ring]:[]))])}{filter('Rider',rider,setRider,[...new Set(notificationSamples.flatMap(r=>r.rider?[r.rider]:[]))])}</div><button className="rings-link" onClick={reset}>Clear filters</button></div>:null}<div className="rings-schedule-toolbar"><p className="rings-help" role="status">{visible.length} of {notificationSamples.length} messages</p><button className="rings-link" disabled={!visible.some(r=>!read.includes(r.id))} onClick={()=>{keyboard.hide();mark(visible.map(r=>r.id));}}>Mark shown as read</button></div>{error?<p className="rings-error" role="alert">{error}</p>:null}<div className="rings-schedule" role="list" aria-label="Notification history">{visible.map(r=><div key={r.id} role="listitem"><RecordPanel title={r.subject} accessory={<div className="rings-entry-rollups">{r.asOf?<span className="rings-badge">As of {r.asOf}</span>:null}<span className="rings-badge" data-tone={read.includes(r.id)?'muted':'blue'}>{read.includes(r.id)?'Read':'Unread'}</span></div>}>{normalizeMessage(r.body,r.alert).map((row,i)=><div className="rings-class-related-data" key={i}><RecordLine label={`${row.status}: ${row.name}${row.start?`, Start ${row.start}`:''}`}><span className="rings-badge rings-time-cell" title={row.start?'Start time':'Start time not supplied'}>{row.start?.replace(/\s*(AM|PM)$/i,(_,v)=>v[0])||'—'}</span><span className="rings-class-cell">{row.classIds.length?<span className="rings-badge rings-class-id" data-tone="blue">C# {row.classIds.join(', ')}</span>:null}<span className="rings-class-name" title={row.name}>{row.name}</span></span><span className="rings-badge rings-status-badge" data-tone={row.status==='NOW'?'green':'blue'}>{row.status}</span></RecordLine>{row.tokens.length||row.entries.length?<div className="rings-entry-line"><div className="rings-entry-rollups">{row.entries.map((entry,j)=><span className="rings-pill" key={`e${j}`}>{entry}</span>)}{row.tokens.map((token,j)=><span className="rings-badge" key={`t${j}`}><span className="rings-token-label">{token.label}</span>{token.value}</span>)}</div></div>:null}</div>)}{r.kind==='support'?<div className="rings-record-content"><p className="rings-message-body">{r.body}</p></div>:null}{r.sponsor||r.variation?<div className="rings-entry-line"><div className="rings-entry-rollups">{r.sponsor?<span className="rings-help">Sponsored by {r.sponsor}</span>:null}{r.variation?<span className="rings-badge">Example variation</span>:null}</div></div>:null}</RecordPanel></div>)}</div>{!visible.length?<div className="rings-section"><h2>No matching messages</h2><p className="rings-help">Try another name or clear the filters.</p><button className="rings-secondary" onClick={reset}>Show all messages</button></div>:null}<p className="rings-prototype-note">{notificationSamples.length} sample messages, including one sponsor variation. Read state is saved in this browser; there is no live SMS connection.</p></main></MobileScroll></>;
}

export default function Prototype({apiBase,accessControl}:{apiBase?:string;accessControl?:ReactNode}){
 const [dark,setDark]=useState(false);const [desktop,setDesktop]=useState(()=>{const view=new URLSearchParams(window.location.search).get('view');return view==='desktop';});const [page,setPage]=useState<'recognize'|'setup'|'schedule'|'alerts'|'feed'>(()=>new URLSearchParams(window.location.search).get('page')==='notification-feed'?'feed':new URLSearchParams(window.location.search).get('page')==='sms-alert-optins'?'alerts':'recognize');const [profile,setProfile]=useState<Profile|null>(null);const keyboard=useKeyboard();const {screenRef}=useScreenPortal();
 useEffect(()=>{const screen=screenRef.current;if(screen){screen.dataset.appTheme=dark?'dark':'white';screen.dataset.appView=desktop?'desktop':'mobile';}return()=>{if(screen){delete screen.dataset.appTheme;delete screen.dataset.appView;}};},[dark,desktop]);
 function changeViewport(){keyboard.hide();const next=!desktop;setDesktop(next);const url=new URL(window.location.href);url.searchParams.set('view',next?'desktop':'mobile');window.history.replaceState(null,'',url);}
 function navigate(next:typeof page){keyboard.hide();setPage(next);}
 return <div className="rings-combined" data-theme={dark?'dark':'white'} data-view={desktop?'desktop':'mobile'}><header className="rings-app-header"><div className="rings-app-brand"><img src={assetPath("/ringstatus-logo.svg")} alt="RingStatus" draggable={false}/><div className="rings-view-controls">{accessControl}<button className="rings-view-switch" onClick={changeViewport}>{desktop?'Mobile view':'Desktop view'}</button><div className="rings-modes" role="group" aria-label="Presentation version"><button aria-pressed={!dark} onClick={()=>{keyboard.hide();setDark(false);}}>White</button><button aria-pressed={dark} onClick={()=>{keyboard.hide();setDark(true);}}>Dark</button></div></div></div><nav className="rings-app-nav" aria-label="RingStatus">{(['recognize','setup','schedule','alerts','feed'] as const).map(p=><button key={p} aria-current={p===page?'page':undefined} onClick={()=>navigate(p)}>{p==='recognize'?'Recognize':p==='setup'?'Barn setup':p==='schedule'?'Schedule':p==='alerts'?'SMS alerts':'Feed'}</button>)}</nav></header><div className="rings-page" hidden={page!=='recognize'}><Recognition apiBase={apiBase} active={page==='recognize'} onProfile={setProfile} onContinue={()=>navigate('setup')}/></div><div className="rings-page" hidden={page!=='setup'}><Onboarding apiBase={apiBase} active={page==='setup'} profile={profile}/></div><div className="rings-page" hidden={page!=='schedule'}><Schedule active={page==='schedule'}/></div><div className="rings-page" hidden={page!=='alerts'}><SmsAlertOptins/></div><div className="rings-page" hidden={page!=='feed'}><NotificationFeed active={page==='feed'}/></div></div>;
}
